'use client';
import{jsx as _jsx}from"react/jsx-runtime";
import{useContext}from'react';
import{DropdownMenuContext}from'../DropdownMenu/DropdownMenu.js';
import{Slot}from'../Slot/Slot.js';
import{customizePart}from'../customization.js';
export function DropdownMenuItem({className,slotProps,label,disabled=false,onSelect,asChild=false,ref,style,children,...rest}){
const menu=useContext(DropdownMenuContext);
const customized=customizePart(slotProps?.root,'cieo cieo-dropdown-menu-item',style,className);
const handleSelect=()=>{
if(disabled)
return;
onSelect?.();
menu?.close();
};
if(asChild){
return(_jsx(Slot,{asChild:true,ref:ref,...rest,role:"menuitem","aria-label":label,"aria-disabled":disabled||undefined,onClick:handleSelect,className:"cieo cieo-dropdown-menu-item",style:style,...customized,children:children}));
}
return(_jsx("button",{ref:ref,...rest,type:"button",role:"menuitem","aria-label":label,disabled:disabled,onClick:handleSelect,className:"cieo cieo-dropdown-menu-item",style:style,...customized,children:children??label}));
}
